export const sesiones = [
  { lenguaje: 'CSS', minutos: 20 },
  { lenguaje: 'JavaScript', minutos: 40 },
  { lenguaje: 'CSS', minutos: 25 },
];

export function resumir(datos, lenguaje) {
  const visibles = datos.filter(
    (sesion) => !lenguaje || sesion.lenguaje === lenguaje,
  );
  const minutos = visibles.reduce((total, sesion) => total + sesion.minutos, 0);
  return { visibles, minutos };
}

