export type Curso = { titulo: string; minutos: number };

export type Resultado =
  | { estado: 'valido'; curso: Curso }
  | { estado: 'ausente' }
  | { estado: 'invalido' };

export function analizar(entrada: unknown): Resultado {
  if (typeof entrada !== 'object' || entrada === null) return { estado: 'invalido' };
  if (!('titulo' in entrada)) return { estado: 'ausente' };

  const titulo = entrada.titulo;
  const minutos = 'minutos' in entrada ? entrada.minutos : undefined;

  if (typeof titulo !== 'string' || !titulo.trim()) return { estado: 'invalido' };
  if (typeof minutos !== 'number' || !Number.isFinite(minutos) || minutos <= 0) {
    return { estado: 'invalido' };
  }
  return { estado: 'valido', curso: { titulo, minutos } };
}

