import React, { useRef, useState } from 'react';

import { Fila } from './Fila.jsx';
import './tablero.css';

export default function App() {
  const [tareas, setTareas] = useState([{ id: 1, texto: 'Leer una guía', hecha: false }]);
  const [texto, setTexto] = useState('');
  const [pendientes, mostrarPendientes] = useState(false);
  const siguienteId = useRef(2);
  const visibles = pendientes ? tareas.filter(tarea => !tarea.hecha) : tareas;

  function agregar(event) {
    event.preventDefault();
    const valor = texto.trim();
    if (!valor) return;
    const id = siguienteId.current++;
    setTareas(actuales => [...actuales, { id, texto: valor, hecha: false }]);
    setTexto('');
  }

  function cambiar(id) {
    setTareas(actuales => actuales.map(tarea =>
      tarea.id === id ? { ...tarea, hecha: !tarea.hecha } : tarea
    ));
  }

  return (
    <main className="tablero">
      <h1>Tablero</h1>
      <form className="tablero-formulario" onSubmit={agregar}>
        <label htmlFor="tarea">Nueva tarea</label>
        <input id="tarea" value={texto} onChange={e => setTexto(e.target.value)} />
        <button type="submit">Agregar</button>
      </form>
      <label>
        <input type="checkbox" checked={pendientes} onChange={e => mostrarPendientes(e.target.checked)} />
        Solo pendientes
      </label>
      {visibles.length ? (
        <ul className="tablero-lista">{visibles.map(tarea => <Fila key={tarea.id} tarea={tarea} cambiar={cambiar} />)}</ul>
      ) : <p>No hay tareas en este filtro.</p>}
    </main>
  );
}

