    private final Map<String, Integer> cantidades = new HashMap<>();

    String alta(String id, int cantidad) {
        if (cantidad < 0) return "Cantidad inválida";
        if (cantidades.putIfAbsent(id, cantidad) != null) return "Duplicado";
        return "Artículo añadido";
    }

    int cantidad(String id) {
        return cantidades.getOrDefault(id, 0);
    }
}

