#ifndef VCODE_INVENTARIO_HPP
#define VCODE_INVENTARIO_HPP

#include <algorithm>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

struct Articulo {
    std::string id;
    int cantidad;
};

inline std::optional<int> buscar(const std::vector<Articulo>& inventario, std::string_view id) {
    const auto encontrado = std::ranges::find(inventario, id, &Articulo::id);
    if (encontrado == inventario.end()) return std::nullopt;
    return encontrado->cantidad;
}

#endif

