CREATE TABLE temas_taller (
  id INTEGER PRIMARY KEY,
  nombre TEXT NOT NULL UNIQUE
);
CREATE TABLE sesiones_taller (
  id INTEGER PRIMARY KEY,
  tema_id INTEGER NOT NULL REFERENCES temas_taller(id),
  minutos INTEGER NOT NULL CHECK (minutos > 0)
);

INSERT INTO temas_taller VALUES (1, 'CSS'), (2, 'SQL'), (3, 'HTML');
INSERT INTO sesiones_taller VALUES (1, 1, 20), (2, 1, 25), (3, 2, 30);

CREATE INDEX sesiones_taller_por_tema ON sesiones_taller (tema_id);

SELECT t.nombre, coalesce(sum(s.minutos), 0) AS minutos
FROM temas_taller AS t
LEFT JOIN sesiones_taller AS s ON s.tema_id = t.id
GROUP BY t.id, t.nombre
ORDER BY minutos DESC, t.nombre;
